CREATE TYPE "age_rating_enum" AS ENUM (
  '0+',
  '6+',
  '12+',
  '16+',
  '18+'
);

CREATE TYPE "mpaa_rating_enum" AS ENUM (
  'G',
  'PG',
  'PG-13',
  'R',
  'NC-17'
);

CREATE TABLE "subscription_type" (
  "subscription_type_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "app_user" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "last_name" varchar(255),
  "first_name" varchar(255),
  "middle_name" varchar(255),
  "registration_date" timestamptz NOT NULL DEFAULT (now()),
  "subscription_type_id" integer,
  "subscription_expiry_date" date
);

CREATE TABLE "review" (
  "review_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" integer NOT NULL,
  "media_id" integer NOT NULL,
  "rating" smallint CHECK (rating BETWEEN 1 AND 10),
  "comment_text" text,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "user_list" (
  "list_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" integer NOT NULL,
  "list_name" varchar(255) NOT NULL
);

CREATE TABLE "user_list_media" (
  "list_id" integer NOT NULL,
  "media_id" integer NOT NULL,
  PRIMARY KEY ("list_id", "media_id")
);

CREATE TABLE "country" (
  "country_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "media_country" (
  "media_id" integer NOT NULL,
  "country_id" integer NOT NULL,
  PRIMARY KEY ("media_id", "country_id")
);

CREATE TABLE "genre" (
  "genre_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "media_genre" (
  "media_id" integer NOT NULL,
  "genre_id" integer NOT NULL,
  PRIMARY KEY ("media_id", "genre_id")
);

CREATE TABLE "media" (
  "media_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "ru_title" varchar(255),
  "en_title" varchar(255),
  "original_title" varchar(255),
  "description" text,
  "short_description" text,
  "slogan" text,
  "release_year" integer,
  "duration_minutes" integer,
  "poster_url" text,
  "poster_preview_url" text,
  "cover_url" text,
  "logo_url" text,
  "age_rating" age_rating_enum,
  "rating_mpaa" mpaa_rating_enum,
  "budget_value" numeric(18,2),
  "worldwide_gross" numeric(18,2),
  "media_type" varchar(50) CHECK (media_type IN ('movie', 'series', 'cartoon', 'anime', 'animated-series', 'other'))
);

CREATE TABLE "person" (
  "person_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "last_name" varchar(255),
  "first_name" varchar(255),
  "middle_name" varchar(255),
  "birth_date" date,
  "bio" text
);

CREATE TABLE "role" (
  "role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "media_person_role" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "media_id" integer NOT NULL,
  "person_id" integer NOT NULL,
  "role_id" integer NOT NULL
);

CREATE TABLE "connection_type" (
  "connection_type_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "connected_media" (
  "media_id" integer NOT NULL,
  "parent_media_id" integer NOT NULL,
  "connection_type_id" integer NOT NULL,
  CONSTRAINT "chk_connected_media_not_self" CHECK (media_id <> parent_media_id),
  PRIMARY KEY ("media_id", "parent_media_id", "connection_type_id")
);

CREATE TABLE "season" (
  "season_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "media_id" integer NOT NULL,
  "season_number" integer NOT NULL,
  "title" varchar(255)
);

CREATE TABLE "episode" (
  "episode_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "season_id" integer NOT NULL,
  "episode_number" integer NOT NULL,
  "title" varchar(255),
  "duration_minutes" integer,
  "description" text
);

CREATE INDEX "idx_app_user_subscription_type_id" ON "app_user" ("subscription_type_id");

CREATE INDEX "idx_review_user_id" ON "review" ("user_id");

CREATE INDEX "idx_review_media_id" ON "review" ("media_id");

CREATE INDEX "idx_user_list_user_id" ON "user_list" ("user_id");

CREATE INDEX "idx_user_list_media_media_id" ON "user_list_media" ("media_id");

CREATE INDEX "idx_media_country_country_id" ON "media_country" ("country_id");

CREATE INDEX "idx_media_genre_genre_id" ON "media_genre" ("genre_id");

CREATE INDEX "idx_media_type" ON "media" ("media_type");

CREATE INDEX "idx_media_release_year" ON "media" ("release_year");

CREATE UNIQUE INDEX "uq_media_person_role" ON "media_person_role" ("media_id", "person_id", "role_id");

CREATE INDEX "idx_media_person_role_person_id" ON "media_person_role" ("person_id");

CREATE INDEX "idx_media_person_role_role_id" ON "media_person_role" ("role_id");

CREATE INDEX "idx_connected_media_parent_media_id" ON "connected_media" ("parent_media_id");

CREATE INDEX "idx_connected_media_connection_type_id" ON "connected_media" ("connection_type_id");

CREATE UNIQUE INDEX "uq_season_media_number" ON "season" ("media_id", "season_number");

CREATE UNIQUE INDEX "uq_episode_season_number" ON "episode" ("season_id", "episode_number");

